using System; using System.Data;  public partial class _Default : System.Web.UI.Page {     protected void Page_Load(object sender, EventArgs e)     {         // 1. SESSION CHECK: Validate user is logged in         if (Session["username"] == null)         {             Response.Redirect("Login.aspx");             return;         }          // Display username from Session         lblUser.Text = Session["username"].ToString(); 
 if (!IsPostBack)         {             // Initialize academic events in Session if not already present             if (Session["AcademicEvents"] == null)             {                 DataTable dt = new DataTable();                 dt.Columns.Add("Date");                 dt.Columns.Add("Event Name");                  // Sample academic events for practical demo                 dt.Rows.Add("15/07/2026", "College Reopening & Orientation");                 dt.Rows.Add("20/08/2026", "Internal Assessment Exam 1");                 dt.Rows.Add("02/10/2026", "Gandhi Jayanti (Holiday)");                 dt.Rows.Add("15/11/2026", "Semester End Theory Exam");                 dt.Rows.Add("30/11/2026", "Final Project Submission & Viva");                  Session["AcademicEvents"] = dt;             }              BindEvents();         }     }      // 2. RICH CONTROL EVENT: Date Selection on Calendar     protected void Calendar1_SelectionChanged(object sender, EventArgs e)     {         lblSelectedDate.Text = Calendar1.SelectedDate.ToShortDateString();         lblEventMsg.Text = ""; 
   private void BindEvents()     {         gvEvents.DataSource = (DataTable)Session["AcademicEvents"];         gvEvents.DataBind();     }      // 3. SESSION CLEAR: Logout     protected void btnLogout_Click(object sender, EventArgs e)     {         Session.Clear();         Session.Abandon();         Response.Redirect("Login.aspx");     } } 
